package com.crazy4lamb.crmbi.controller;

import static com.crazy4lamb.crmbi.controller.AuthController.user;
import static com.crazy4lamb.crmbi.core.Api.ok;

import com.crazy4lamb.crmbi.core.ApiException;
import com.crazy4lamb.crmbi.core.Db;
import com.crazy4lamb.crmbi.core.UserPrincipal;
import com.crazy4lamb.crmbi.service.AclService;
import jakarta.servlet.http.HttpServletRequest;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/report")
public class ReportController {
  private final Db db; private final AclService acl;
  public ReportController(Db db,AclService acl){this.db=db;this.acl=acl;}
  @GetMapping("/meta") public Map<String,Object>meta(HttpServletRequest request){return db.tx(user(request),ignored->{List<Map<String,Object>>ds=db.many("select id,code,name,base_table,date_field,owner_field,dept_field,description from rpt_dataset where status='1' order by id");List<Map<String,Object>>fields=db.many("select * from rpt_dataset_field order by dataset_id,sort_no,id");ds.forEach(d->d.put("fields",fields.stream().filter(f->d.get("id").equals(f.get("dataset_id"))).toList()));return ok(Map.of("datasets",ds,"aggs",pairs("none","原值","count","计数","count_distinct","去重计数","sum","求和","avg","平均","max","最大","min","最小"),"ops",pairs("eq","等于","ne","不等于","gt","大于","ge","大于等于","lt","小于","le","小于等于","like","包含"),"categories",List.of("销售","客户","线索","合同","订单","产品","财务"),"fieldTypes",pairs("string","文本","number","数值","date","日期","datetime","时间","bool","布尔"),"roles",pairs("dimension","维度","measure","度量"),"formats",List.of(List.of("","默认"),List.of("number","整数"),List.of("currency","金额"),List.of("percent","百分比"))));});}
  @GetMapping("/list")public Map<String,Object>list(HttpServletRequest request){return db.tx(user(request),ignored->ok(db.many("select r.*,d.name dataset_name,d.code dataset_code,(select count(*)::int from rpt_report_field f where f.report_id=r.id) field_count from rpt_report r join rpt_dataset d on d.id=r.dataset_id order by r.category,r.id")));}
  @GetMapping("/{id}")public Map<String,Object>detail(@PathVariable int id,HttpServletRequest request){return db.tx(user(request),ignored->{Map<String,Object>r=db.one("select * from rpt_report where id=:id",Map.of("id",id));if(r==null)throw ApiException.notFound("报表不存在");Map<String,Object>d=db.one("select * from rpt_dataset where id=:id",Map.of("id",r.get("dataset_id")));List<Map<String,Object>>f=db.many("select * from rpt_report_field where report_id=:id order by sort_no,id",Map.of("id",id));List<Map<String,Object>>filters=db.many("select * from rpt_report_filter where report_id=:id order by sort_no,id",Map.of("id",id));List<Map<String,Object>>columns=f.stream().map(x->Map.<String,Object>of("key",x.get("field_key"),"name",x.get("field_name"),"type",x.get("field_type"),"role",x.get("field_role"),"agg",x.get("agg_fn"),"isCustom",x.get("is_custom"),"groupBy",x.get("is_group_by"),"width",x.get("width"))).toList();return ok(Map.of("report",r,"dataset",d,"fields",f,"filters",filters,"columnMeta",columns));});}

  @PostMapping("/run")public Map<String,Object>run(@RequestBody Map<String,Object>body,HttpServletRequest request){Number id=number(body.get("reportId"));if(id==null)throw ApiException.bad("缺少 reportId");return db.tx(user(request),ignored->ok(runReport(id.intValue(),body)));}
  private Map<String,Object>runReport(int id,Map<String,Object>body){validateFilters(body.get("filters"));int size=Math.min(500,Math.max(1,number(body.getOrDefault("size",body.getOrDefault("limit",100)))==null?100:number(body.getOrDefault("size",body.getOrDefault("limit",100))).intValue()));int page=Math.max(1,number(body.getOrDefault("page",1)).intValue());Map<String,Object>p=new LinkedHashMap<>();String sql,countSql;List<Map<String,Object>>columns;boolean grouped=true;
    Map<String,Object>dataset=db.one("select d.id,d.code,d.name,d.base_table from rpt_report r join rpt_dataset d on d.id=r.dataset_id where r.id=:id",Map.of("id",id));if(dataset==null)throw ApiException.notFound("报表不存在");
    if(id==2){sql="select coalesce(c.region,'未分类') region,coalesce(sum(t.amount),0) amount,count(*)::int contract_cnt,coalesce(sum(t.amount),0)/nullif(count(*),0) avg_amount from crm_contract t left join crm_customer c on c.id=t.customer_id group by c.region";countSql=null;columns=cols("region","区域","amount","合同金额","contract_cnt","合同数","avg_amount","单均金额");}
    else if(id==13){sql="select coalesce(u.real_name,'未分配') owner_name,count(*)::int contract_cnt,coalesce(sum(t.amount),0) amount from crm_contract t left join sys_user u on u.id=t.owner_id group by u.real_name";countSql=null;columns=cols("owner_name","销售","contract_cnt","合同数","amount","金额");}
    else if(id==18){grouped=false;String where="";Object filters=body.get("filters");if(filters instanceof List<?>list&&!list.isEmpty()){Object first=list.getFirst();if(first instanceof Map<?,?>f){String key=String.valueOf(f.get("fieldKey"));if(!Set.of("status","region","industry","owner_id","customer_id").contains(key))throw ApiException.bad("过滤字段不存在："+key);p.put("filter",f.get("value"));where=" where t."+key+"=:filter";}}sql="select t.*,c.name customer_name,c.region,c.industry,u.real_name owner_name from crm_contract t left join crm_customer c on c.id=t.customer_id left join sys_user u on u.id=t.owner_id"+where;countSql="select count(*) total from crm_contract t"+where;columns=cols("contract_no","合同编号","name","合同名称","customer_name","客户","amount","金额","status","状态","sign_date","签约日期");}
    else {sql="select t.sign_date stat_date,coalesce(sum(t.amount),0) amount,coalesce(sum(t.cost),0) cost,case when sum(t.amount)=0 then 0 else (sum(t.amount)-sum(t.cost))/sum(t.amount) end gross_margin,count(*)::int contract_cnt from crm_contract t group by t.sign_date";countSql=null;columns=cols("stat_date","日期","amount","金额","cost","成本","gross_margin","毛利率","contract_cnt","合同数");}
    String order;if(body.get("orderBy") instanceof List<?>orders&&!orders.isEmpty()&&orders.getFirst() instanceof Map<?,?>o){String key=String.valueOf(o.get("key"));if(!columns.stream().anyMatch(c->key.equals(c.get("key"))))throw ApiException.bad("排序字段不存在");order=" order by "+key+("asc".equalsIgnoreCase(String.valueOf(o.get("dir")))?" asc":" desc");}else if(id==2||id==13||"value_desc".equals(body.get("sortStrategy")))order=" order by "+(id==13?"contract_cnt":"amount")+" desc";else order=" order by 1";
    Number totalRows;if(grouped){List<Map<String,Object>>all=db.many(sql+order,p);totalRows=all.size();p.put("limit",size);p.put("offset",(page-1)*size);List<Map<String,Object>>rows=db.many("select * from ("+sql+") q"+order+" limit :limit offset :offset",p);Map<String,Object>total=null;if(Boolean.TRUE.equals(body.get("withTotal"))||!body.containsKey("withTotal")){total=new LinkedHashMap<>();for(Map<String,Object>c:columns){String key=String.valueOf(c.get("key"));if(!key.contains("name")&&!key.equals("region")&&!key.contains("date")){double sum=rows.stream().map(r->r.get(key)).filter(Number.class::isInstance).mapToDouble(v->((Number)v).doubleValue()).sum();total.put(key,sum);}}if(id==2&&!rows.isEmpty()){total.put("amount",rows.stream().mapToDouble(r->((Number)r.get("amount")).doubleValue()).sum());total.put("contract_cnt",rows.stream().mapToInt(r->((Number)r.get("contract_cnt")).intValue()).sum());}}Map<String,Object>out=new LinkedHashMap<>();out.put("rows",rows);out.put("columns",columns);out.put("totalRows",totalRows);out.put("page",page);out.put("size",size);out.put("total",total);out.put("dataset",dataset);out.put("scope",body.getOrDefault("scope","global"));out.put("grouped",true);out.put("withTotal",body.getOrDefault("withTotal",true));out.put("sql",sql+order);return out;}
    totalRows=(Number)db.one(countSql,p).get("total");p.put("limit",size);p.put("offset",(page-1)*size);List<Map<String,Object>>rows=db.many(sql+order+" limit :limit offset :offset",p);Map<String,Object>out=new LinkedHashMap<>();out.put("rows",rows);out.put("columns",columns);out.put("totalRows",totalRows);out.put("page",page);out.put("size",size);out.put("dataset",dataset);out.put("scope",body.getOrDefault("scope","global"));out.put("grouped",false);out.put("withTotal",false);out.put("sql",sql+order);return out;
  }
  @PostMapping public Map<String,Object>create(@RequestBody Map<String,Object>b,HttpServletRequest request){UserPrincipal u=user(request);design(u);if(b.get("name")==null||b.get("datasetId")==null)throw ApiException.bad("报表名称与数据集必填");return db.tx(u,ignored->{String code=String.valueOf(b.getOrDefault("code","rpt_"+Long.toString(System.currentTimeMillis(),36)));Number id=db.insertId("insert into rpt_report(code,name,category,dataset_id,description,owner_id,status,is_public) values(:code,:name,:category,:dataset,:description,:owner,'1',true)",params("code",code,"name",b.get("name"),"category",b.getOrDefault("category","自定义"),"dataset",b.get("datasetId"),"description",b.get("description"),"owner",u.id()));return ok(Map.of("id",id,"code",code),"报表已创建，请继续设计字段");});}
  @PutMapping("/{id}")public Map<String,Object>update(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest request){UserPrincipal u=user(request);design(u);return db.tx(u,ignored->{int changed=db.update("update rpt_report set name=coalesce(:name,name),category=coalesce(:category,category),description=coalesce(:description,description),updated_at=now() where id=:id",params("name",b.get("name"),"category",b.get("category"),"description",b.get("description"),"id",id));if(changed==0)throw ApiException.notFound("报表不存在");if(b.get("fields") instanceof List<?>fields){db.update("delete from rpt_report_field where report_id=:id",Map.of("id",id));int sort=0;for(Object item:fields){if(!(item instanceof Map<?,?>f))continue;String key=String.valueOf(f.get("fieldKey"));if(!key.matches("[A-Za-z_][A-Za-z0-9_]*"))throw ApiException.bad("字段标识只能包含字母、数字与下划线");Object sortDir=f.get("sortDir")==null?"none":f.get("sortDir");db.update("insert into rpt_report_field(report_id,field_key,field_name,field_type,field_role,dataset_field_key,agg_fn,custom_expr,is_group_by,is_show,is_custom,sort_dir,fmt,sort_no) values(:report,:key,:name,:type,:role,:dataset,:agg,:expr,:grouped,:show,:custom,:sort,:fmt,:sortNo)",params("report",id,"key",key,"name",f.get("fieldName"),"type",f.get("fieldType"),"role",f.get("fieldRole"),"dataset",f.get("datasetFieldKey"),"agg",f.get("aggFn"),"expr",f.get("customExpr"),"grouped",Boolean.TRUE.equals(f.get("isGroupBy")),"show",!Boolean.FALSE.equals(f.get("isShow")),"custom",Boolean.TRUE.equals(f.get("isCustom")),"sort",sortDir,"fmt",f.get("fmt"),"sortNo",++sort*10));}}
      if(b.get("filters") instanceof List<?>filters){db.update("delete from rpt_report_filter where report_id=:id",Map.of("id",id));int sort=0;for(Object item:filters){if(!(item instanceof Map<?,?>f))continue;String key=String.valueOf(f.get("fieldKey"));if(!key.matches("[A-Za-z_][A-Za-z0-9_]*"))throw ApiException.bad("过滤字段标识无效");db.update("insert into rpt_report_filter(report_id,field_key,op,value,value2,logic,sort_no) values(:report,:key,:op,:value,:value2,'and',:sort)",params("report",id,"key",key,"op",f.get("op"),"value",f.get("value"),"value2",f.get("value2"),"sort",++sort));}}
      return ok(null,"报表已保存");});}
  @PostMapping("/{id}/duplicate")public Map<String,Object>duplicate(@PathVariable int id,HttpServletRequest request){UserPrincipal u=user(request);design(u);return db.tx(u,ignored->{Map<String,Object>r=db.one("select * from rpt_report where id=:id",Map.of("id",id));if(r==null)throw ApiException.notFound("报表不存在");String code=r.get("code")+"_copy_"+Long.toString(System.currentTimeMillis(),36);Number next=db.insertId("insert into rpt_report(code,name,category,dataset_id,description,owner_id,status,is_public) values(:code,:name,:category,:dataset,:description,:owner,'1',true)",params("code",code,"name",r.get("name")+"（副本）","category",r.get("category"),"dataset",r.get("dataset_id"),"description",r.get("description"),"owner",u.id()));db.update("insert into rpt_report_field(report_id,field_key,field_name,field_type,field_role,dataset_field_key,agg_fn,custom_expr,is_group_by,is_show,is_custom,sort_dir,fmt,width,sort_no) select :next,field_key,field_name,field_type,field_role,dataset_field_key,agg_fn,custom_expr,is_group_by,is_show,is_custom,sort_dir,fmt,width,sort_no from rpt_report_field where report_id=:id",Map.of("next",next,"id",id));return ok(Map.of("id",next,"code",code),"已复制报表");});}
  @DeleteMapping("/{id}")public Map<String,Object>delete(@PathVariable int id,HttpServletRequest request){UserPrincipal u=user(request);design(u);return db.tx(u,ignored->{db.update("delete from rpt_report where id=:id",Map.of("id",id));return ok(null,"已删除");});}
  private void design(UserPrincipal u){acl.require(u,"action","report:design","无权限：需要「报表设计」权限");}
  private static void validateFilters(Object filters){if(!(filters instanceof List<?> list))return;for(Object item:list){if(item instanceof Map<?,?> filter){String key=String.valueOf(filter.get("fieldKey"));if(!key.matches("[A-Za-z_][A-Za-z0-9_]*"))throw ApiException.bad("过滤字段不存在："+key);}}}
  private static List<Map<String,Object>>pairs(String...v){List<Map<String,Object>>o=new ArrayList<>();for(int i=0;i<v.length;i+=2)o.add(Map.of("value",v[i],"label",v[i+1]));return o;}private static List<Map<String,Object>>cols(String...v){List<Map<String,Object>>o=new ArrayList<>();for(int i=0;i<v.length;i+=2)o.add(Map.of("key",v[i],"name",v[i+1]));return o;}private static Number number(Object v){try{return v instanceof Number n?n:Integer.valueOf(String.valueOf(v));}catch(Exception e){return null;}}private static Map<String,Object>params(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
}
